from pathlib import Path
import json,hashlib,html
root=Path(__file__).resolve().parents[1];out=root/'output/tolerance-verification'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
groups={name:read(out/name) for name in ['results.json','ui-results.json','built-results.json','pdf-results.json']}
assert all(r['status']=='PASS' for g in groups.values() for r in g['results'])
unit=read(out/'unit-results.json');assert unit['numTotalTests']==unit['numPassedTests']==318
count=unit['numPassedTests']+sum(len(g['results']) for g in groups.values());assert count==336
render=read(out/'render-results.json');assert render['status']=='PASS' and render['views']==4
