unchanged={f:hashlib.sha256((root/f).read_bytes()).hexdigest() for f in old['unchangedDirectSdkFiles']};assert unchanged==old['unchangedDirectSdkFiles'];assert not (root/'functions').exists()
for f in ['src/domain/bs8666.ts','src/domain/bsTemplates.ts','src/domain/model.ts','src/domain/version.ts','src/domain/engine.ts']:
    assert (root/f).exists()
source_files=['src/domain/bsTolerances.ts','src/components/BSTolerances.tsx','src/components/BarStandard.tsx','src/styles.css','src/data/excelPrint.ts','src/data/bsTolerancePdf.ts','src/data/cuttingSchedulePdf.ts','src/App.tsx','package.json','package-lock.json']
sources={f:hashlib.sha256((root/f).read_bytes()).hexdigest() for f in source_files}
ctx=read(out/'context.json');file_hashes={}
for name,ctype in [('BS-Table4-draft.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'),('BS-Table4-A4-draft.pdf','application/pdf')]:
    sha=hashlib.sha256((out/name).read_bytes()).hexdigest();assert any(a['sha256']==sha and a['contentType']==ctype for a in ctx['artifacts']);file_hashes[name]=sha
reference_sha=hashlib.sha256((root/'Referrence/BS 8666.pdf').read_bytes()).hexdigest();assert reference_sha=='9c6fa5d0bafd0a8761f14d1611c582d5db7d89710eaaf0910b5dc7c493e0cb43'
summary={'version':'0.28.0','status':'PASS','softwareScenarios':count,'unitTests':318,'directExportScenarios':8,'devUiScenarios':4,'builtUiScenarios':4,'pdfDiagnosticScenarios':2,'renderedWorkbookViews':4,'visuallyInspectedPdfPages':10,'pdfStructuralPages':34,'nativeExcelPrintingVerified':False,'fullSystemAcceptance':False,'rulesDeployment':'User-managed; explicitly declined','cloudChanges':False,'unchangedAuthRulesConfig':unchanged,'referenceSha256':reference_sha,'sourceFiles':sources,'artifactSha256':file_hashes,'checkpoint':checkpoint}
(out/'verification-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
captions={'built-reference.png':'ช่วงอ้างอิงในหน้าตรวจ Mark จากรุ่น build','built-mobile-ranges.png':'มือถือเลื่อนไปดูช่วงขอบล่าง/บนได้','tolerances.png':'ชีต BS Tolerances จาก Frozen','bbs-print.png':'รูปเหล็กและปริมาณ Frozen คงเดิม','rebar-summary.png':'สรุปเหล็กและน้ำหนักเดิม','large-last-record.png':'ข้อมูลครบถึงสมาชิกที่520','a4-page-1.png':'ตารางตัด/ดัด A4 จากงานส่งออกจริง','a4-page-5.png':'ภาคผนวก Table4 อ้างเลขตาราง/Mark เดียวกัน','multiple-page-25.png':'ตารางต่อเนื่อง หน้า25','multiple-page-26.png':'หัวตารางซ้ำและเลขอ้างอิงครบ หน้า26','precision-page-3.png':'ค่าที่เกินความละเอียดไม่แสดงช่วงที่คลาดเคลื่อน'}
